<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from "vue";
import { Activity, Bot, Check, ChevronRight, CircleAlert, Cpu, Eye, KeyRound, LockKeyhole, MessageSquare, Network, RotateCcw, Save, Search, Settings2, Shield, Sparkles, TestTube2, UserPlus, X, Zap } from "@lucide/vue";
import { api, bestEffort, formatNumber, json } from "../api";
import type { ConfigField, ModuleStatus, UsageSummary } from "../types";
import EmptyState from "../components/EmptyState.vue";
import StatusDot from "../components/StatusDot.vue";

const emit = defineEmits<{ notify: [tone:"success"|"error"|"info", title:string, detail?:string] }>();
const manifest=ref<{fields:ConfigField[];presets:any[]}>({fields:[],presets:[]});const state=ref<Record<string,any>>({});const providers=ref<any[]>([]);const activeProvider=ref("");const routes=ref<any[]>([]);const usage=ref<UsageSummary|null>(null);const modules=ref<ModuleStatus[]>([]);const permissions=ref<any>({owners:[],admins:[]});const history=ref<any[]>([]);const rollingBack=ref("");
const category=ref("llm");const draft=ref<Record<string,any>>({});const search=ref("");const loading=ref(true);const validating=ref(false);const testing=ref(false);const testResult=ref<any>(null);const pendingChange=ref<any>(null);const applying=ref(false);const rejecting=ref("");const range=ref("today");const adminQQ=ref("");const napcatProbe=ref<any>(null);const probingNapcat=ref(false);const autonomy=ref<any>(null);const controllingAutonomy=ref(false);const groupPolicyId=ref("");const groupPolicy=ref<any>({reply_enabled:true,reply_only_when_mentioned:true,autonomy:true,tools_enabled:true,stickers_enabled:true});const toolList=ref<any[]>([]);const toolLevelOptions=[{value:0,label:"封禁 (0)"},{value:1,label:"只读 (1)"},{value:2,label:"普通用户 (2)"},{value:3,label:"管理员 (3)"},{value:4,label:"Owner (4)"}];
const categories=[{id:"llm",label:"模型控制中心",hint:"提供商、路由与用量",icon:Sparkles},{id:"behavior",label:"自主行为",hint:"主动发言、群策略与社交",icon:Zap},{id:"perception",label:"感知与媒体",hint:"图片、表情、生图与视频",icon:Eye},{id:"expression",label:"表达与节奏",hint:"分段、防抖、语音与互动",icon:MessageSquare},{id:"cognition",label:"认知系统",hint:"灵魂、闸门与跨群记忆",icon:Network},{id:"modules",label:"模块与诊断",hint:"运行状态和降级原因",icon:Activity},{id:"permissions",label:"权限管理",hint:"Owner 与管理员",icon:Shield}];
const fieldGroups:Record<string,string[]>={llm:["llm."],behavior:["autonomy.","permissions.group_policies","qzone.","qq_status."],perception:["vision.","sticker.","image_generation.","bilibili_read."],expression:["reply_split.","debounce.","voice.","meme."],cognition:["soul.","gate.","sylann.","crossgroup."]};
const visibleFields=computed(()=>manifest.value.fields.filter(field=>(fieldGroups[category.value]||[]).some(prefix=>field.path.startsWith(prefix))).filter(field=>field.type!=="group_policies").filter(field=>!search.value||field.label.toLowerCase().includes(search.value.toLowerCase())||field.path.includes(search.value)));
const groupPolicies=computed<Record<string,any>>(()=>draft.value["permissions.group_policies"]??getPath(state.value,"permissions.group_policies")??{});
const changes=computed(()=>Object.entries(draft.value).map(([path,value])=>{const field=manifest.value.fields.find(item=>item.path===path);return{path,value,field,before:getPath(state.value,path),risk:field?.risk||"yellow",restart:field?.restart??true,impact:field?.impact||["模型路由"]}}));
const maxModuleTokens=computed(()=>Math.max(1,...(usage.value?.modules||[]).map(item=>item.total_tokens)));
const availableModels=computed(()=>{const set=new Set<string>();providers.value.forEach(p=>{if(p.model)set.add(p.model);(p.models||[]).forEach((m:string)=>set.add(m))});routes.value.forEach(r=>set.add(r.model));return[...set]});
const currentCategory=computed(()=>categories.find(item=>item.id===category.value)!);
const riskTone=computed(()=>changes.value.some(c=>c.risk==="red")?"red":changes.value.some(c=>c.risk==="yellow")?"yellow":"green");

function getPath(object:any,path:string){return path.split(".").reduce((value,key)=>value?.[key],object)}
function setDraft(path:string,value:any){const before=getPath(state.value,path);if(JSON.stringify(before)===JSON.stringify(value)||(value===""&&manifest.value.fields.find(f=>f.path===path)?.type==="secret")){const next={...draft.value};delete next[path];draft.value=next}else draft.value={...draft.value,[path]:value}}
function policyDefaults(value:any={}){return{reply_enabled:value.reply_enabled!==false,reply_only_when_mentioned:value.reply_only_when_mentioned!==false,autonomy:value.autonomy!==false,tools_enabled:value.tools_enabled!==false,stickers_enabled:value.stickers_enabled!==false}}
function editGroupPolicy(id:string){groupPolicyId.value=id;groupPolicy.value=policyDefaults(groupPolicies.value[id])}
function saveGroupPolicy(){const id=groupPolicyId.value.trim();if(!/^\d{5,16}$/.test(id)){emit("notify","error","请输入有效群号","群号应为 5–16 位数字。");return}const next={...groupPolicies.value,[id]:{...groupPolicy.value}};setDraft("permissions.group_policies",next);groupPolicyId.value="";groupPolicy.value=policyDefaults();emit("notify","info",`已预览群 ${id} 的策略`,"仍需在右侧验证并应用。")}
function removeGroupPolicy(id:string){const next={...groupPolicies.value};delete next[id];setDraft("permissions.group_policies",next)}
function displayValue(field:ConfigField){const value=draft.value[field.path]??getPath(state.value,field.path);if(field.type==="secret")return "";if(field.type==="csv")return Array.isArray(value)?value.join(", "):value??"";return value??""}
function buildPatch(){const patch:Record<string,any>={};for(const [path,value] of Object.entries(draft.value)){const parts=path.split(".");let cursor=patch;parts.forEach((part,index)=>{if(index===parts.length-1)cursor[part]=value;else cursor=cursor[part]||(cursor[part]={})})}return patch}
function flattenPatch(object:any,prefix=""){Object.entries(object||{}).forEach(([key,value])=>{const path=prefix?`${prefix}.${key}`:key;if(value&&typeof value==="object"&&!Array.isArray(value))flattenPatch(value,path);else setDraft(path,value)})}
function applyPreset(item:any){flattenPatch(item.patch);emit("notify","info",`已预览「${item.label}」`,`不会直接保存，请检查右侧变更摘要。`)}
function fieldDescription(field:ConfigField){const pieces=[field.restart?"应用后受控重启":"可直接应用",`影响：${field.impact.join('、')}`];if(field.type==="secret")pieces.unshift(getPath(state.value,field.path)?.configured?"已配置，留空保持原值":"尚未配置");return pieces.join(" · ")}
function inputValue(event:Event,field:ConfigField){const target=event.target as HTMLInputElement;if(field.type==="number")return Number(target.value);if(field.type==="csv")return target.value.split(",").map(item=>item.trim()).filter(Boolean);return target.value}
function formatDate(value:number){if(!value)return "—";return new Date(value*1000).toLocaleString("zh-CN",{month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"})}
function patchPaths(object:any,prefix=""):string[]{return Object.entries(object||{}).flatMap(([key,value])=>{const path=prefix?`${prefix}.${key}`:key;return value&&typeof value==="object"&&!Array.isArray(value)&&!("configured" in (value as Record<string,any>))?patchPaths(value,path):[path]})}
function changeLabel(item:any){const paths=patchPaths(item.patch);return paths.length?paths.map(path=>{const matches=manifest.value.fields.filter(field=>path===field.path||path.startsWith(`${field.path}.`));return(matches.sort((a,b)=>b.path.length-a.path.length)[0]?.label)||path}).join("、"):"配置变更"}
function canRollback(item:any){return item.status==="applied"&&!rollingBack.value}
async function rollbackChange(item:any){if(!canRollback(item))return;if(!window.confirm(`回滚「${changeLabel(item)}」？当前配置将恢复到 ${formatDate(item.created_at)} 前的状态。`))return;rollingBack.value=item.id;try{const result=await api<any>(`/api/config/change-sets/${item.id}/rollback`,json("POST",{}));emit("notify","success",result.restart_scheduled?"已回滚，服务正在受控重启":"配置已回滚",`审计编号 ${item.id}`);window.setTimeout(load,result.restart_scheduled?4500:300)}catch(e:any){emit("notify","error","配置回滚失败",e.message)}finally{rollingBack.value=""}}
function canReject(item:any){return item.status==="pending"&&!rejecting.value}
async function rejectChange(item:any){if(!canReject(item))return;const reason=window.prompt(`驳回「${changeLabel(item)}」的原因（可选）`,"Owner 驳回")||"Owner 驳回";rejecting.value=item.id;try{await api<any>(`/api/config/change-sets/${item.id}/reject`,json("POST",{reason}));emit("notify","success","变更已驳回","当前运行配置未被修改");await load()}catch(e:any){emit("notify","error","配置驳回失败",e.message)}finally{rejecting.value=""}}
async function load(){loading.value=true;try{const [m,s,p,r,u,mod,perm,h,a]=await Promise.all([bestEffort(api<any>("/api/config/manifest"),{fields:[],presets:[]}),bestEffort(api<any>("/api/config/state"),{state:{}}),bestEffort(api<any>("/api/llm/providers"),{providers:[],active:""}),bestEffort(api<any>("/api/llm/routes"),{routes:[]}),bestEffort(api<any>(`/api/llm/usage?range=${range.value}`),null),bestEffort(api<any>("/api/modules/status"),{modules:[]}),bestEffort(api<any>("/api/permissions"),{owners:[],admins:[]}),bestEffort(api<any>("/api/config/change-sets?limit=30"),{changes:[]}),bestEffort(api<any>("/api/autonomy/status"),null)]);manifest.value=m;state.value=s.state||{};providers.value=p.providers||[];activeProvider.value=p.active||"";routes.value=r.routes||[];usage.value=u;modules.value=mod.modules||[];permissions.value=perm;history.value=h.changes||[];autonomy.value=a;loadTools()}finally{loading.value=false}}
async function loadUsage(value:string){range.value=value;try{usage.value=await api<any>(`/api/llm/usage?range=${value}`)}catch(e:any){emit("notify","error","用量读取失败",e.message)}}
async function testProvider(){testing.value=true;testResult.value=null;try{testResult.value=await api<any>("/api/llm/providers/test",json("POST",{provider:draft.value["llm.active_provider"]||activeProvider.value,endpoint:draft.value["llm.endpoint"]||getPath(state.value,"llm.endpoint"),api_key:draft.value["llm.api_key"]||undefined}));emit("notify",testResult.value.ok?"success":"error",testResult.value.ok?"模型连接正常":"模型连接失败",testResult.value.ok?`${testResult.value.latency_ms} ms · ${testResult.value.models?.length||0} 个模型`:testResult.value.message)}catch(e:any){emit("notify","error","连接测试失败",e.message)}finally{testing.value=false}}
async function probeNapcat(){probingNapcat.value=true;napcatProbe.value=null;try{napcatProbe.value=await api<any>("/api/diagnostics/napcat",json("POST",{}));emit("notify","success","NapCat 回路正常",`${napcatProbe.value.latency_ms} ms · 未发送消息`)}catch(e:any){napcatProbe.value={ok:false,message:e.message};emit("notify","error","NapCat 诊断失败",e.message)}finally{probingNapcat.value=false}}
async function controlAutonomy(action:"pause"|"resume"){if(controllingAutonomy.value)return;const pausing=action==="pause";if(pausing&&!window.confirm("暂停后，机器人仍可以回复 @ 和私聊，但不再主动发言。确认吗？"))return;controllingAutonomy.value=true;try{const result=await api<any>(`/api/autonomy/${action}`,json("POST",{}));autonomy.value={...(autonomy.value||{}),enabled:result.enabled,running:!pausing};emit("notify","success",pausing?"自主行为已暂停":"自主行为已恢复",pausing?"QQ 被动回复不受影响":"心跳会按当前群策略继续运行" );await load()}catch(e:any){emit("notify","error","自主控制失败",e.message)}finally{controllingAutonomy.value=false}}
async function prepareChange(){if(!changes.value.length)return;validating.value=true;try{const patch=buildPatch();await api("/api/config/validate",json("POST",{patch}));pendingChange.value=await api("/api/config/change-sets",json("POST",{patch}));}catch(e:any){emit("notify","error","配置校验未通过",e.message)}finally{validating.value=false}}
async function applyChange(){if(!pendingChange.value)return;applying.value=true;try{const result=await api<any>(`/api/config/change-sets/${pendingChange.value.id}/apply`,json("POST",{}));emit("notify","success",result.restart_scheduled?"变更已应用，服务正在受控重启":"配置已经生效",`审计编号 ${pendingChange.value.id}`);pendingChange.value=null;draft.value={};window.setTimeout(load,result.restart_scheduled?4500:300);}catch(e:any){const preflight=String(e.message||"").includes("配置预检失败");emit("notify","error",preflight?"模型配置预检未通过":"配置应用失败",e.message)}finally{applying.value=false}}
async function addAdmin(){try{permissions.value=await api<any>("/api/permissions/admins",json("POST",{qq:Number(adminQQ.value)}));adminQQ.value="";emit("notify","success","管理员已添加")}catch(e:any){emit("notify","error","添加失败",e.message)}}
async function removeAdmin(qq:number){try{permissions.value=await api<any>(`/api/permissions/admins/${qq}`,{method:"DELETE"});emit("notify","success","管理员已移除")}catch(e:any){emit("notify","error","移除失败",e.message)}}
async function loadTools(){try{const r=await api<any>("/api/tools");toolList.value=r.tools||[]}catch(e:any){toolList.value=[]}}
async function updateToolLevel(name:string,newLevel:number){try{await api("/api/tools/level",json("PATCH",{name,min_level:newLevel}));const t=toolList.value.find(x=>x.name===name);if(t){t.min_level=newLevel;t.min_level_name=["banned","readonly","user","admin","owner"][newLevel]||"unknown"}emit("notify","success",`${name} 已更新为 ${["封禁","只读","普通用户","管理员","Owner"][newLevel]}`)}catch(e:any){emit("notify","error","更新失败",e.message)}}
function openSettingsSection(event: Event){const target=(event as CustomEvent<string>).detail;if(categories.some(item=>item.id===target))category.value=target}
onMounted(()=>{load();window.addEventListener("anima:settings-section",openSettingsSection)});
onBeforeUnmount(()=>window.removeEventListener("anima:settings-section",openSettingsSection));
</script>

<template><section class="page settings-page">
  <div class="page-heading"><div><span class="eyebrow">control center</span><h1>改变行为，不用碰 YAML。</h1><p>所有配置先校验、再展示影响，最后才应用；密钥永远不会从后端回显。</p></div></div>
  <div class="settings-layout">
    <aside class="settings-nav panel"><label class="settings-search"><Search :size="15"/><input v-model="search" placeholder="搜索设置"/></label><nav><button v-for="item in categories" :key="item.id" :class="{active:category===item.id}" @click="category=item.id"><component :is="item.icon" :size="17"/><span><strong>{{ item.label }}</strong><small>{{ item.hint }}</small></span><ChevronRight :size="14"/></button></nav></aside>
    <main class="settings-center panel">
      <header class="settings-head"><span :class="`cat-icon ${category}`"><component :is="currentCategory.icon" :size="20"/></span><div><small>SETTINGS / {{ category.toUpperCase() }}</small><h2>{{ currentCategory.label }}</h2><p>{{ currentCategory.hint }}</p></div></header>
      <template v-if="category==='llm'">
        <section class="settings-section"><div class="settings-section-head"><div><h3>快速连接</h3><p>先测试新连接，确认模型列表可用后再生成变更。</p></div><button class="action-button subtle" :disabled="testing" @click="testProvider"><TestTube2 :size="15"/>{{ testing?'测试中':'测试连接' }}</button></div>
          <div class="provider-strip"><button v-for="provider in providers" :key="provider.id" :class="{active:(draft['llm.active_provider']||activeProvider)===provider.id}" @click="setDraft('llm.active_provider',provider.id)"><span><i :class="{configured:provider.configured}"/>{{ provider.label }}</span><small>{{ provider.model }}</small></button></div>
          <div v-if="testResult" class="test-result" :class="{ok:testResult.ok}"><Check v-if="testResult.ok" :size="17"/><CircleAlert v-else :size="17"/><span><strong>{{ testResult.ok?'连接成功':'连接失败' }}</strong><small>{{ testResult.ok?`${testResult.latency_ms} ms · 找到 ${testResult.models?.length||0} 个模型`:testResult.message }}</small></span></div>
        </section>
        <section class="settings-section"><div class="settings-section-head"><div><h3>默认模型与连接参数</h3><p>留空的 API Key 会保持线上原值。</p></div></div><div class="field-grid">
          <div v-for="field in visibleFields.filter(f=>!['providers','routes'].includes(f.type))" :key="field.path" class="field config-field"><div class="field-top"><label :for="field.path">{{ field.label }}</label><span :class="`risk-${field.risk}`">{{ field.risk==='green'?'即时':field.risk==='yellow'?'需重启':'高风险' }}</span></div>
            <label v-if="field.type==='boolean'" class="switch"><input :id="field.path" type="checkbox" :checked="Boolean(displayValue(field))" @change="setDraft(field.path,($event.target as HTMLInputElement).checked)"/><span/></label>
            <select v-else-if="field.type==='select'" :id="field.path" :value="displayValue(field)" @change="setDraft(field.path,($event.target as HTMLSelectElement).value)"><option v-for="option in field.options" :key="option">{{ option }}</option></select>
            <input v-else :id="field.path" :type="field.type==='secret'?'password':field.type==='number'?'number':'text'" :min="field.min" :max="field.max" :value="displayValue(field)" :placeholder="field.type==='secret'?(getPath(state,field.path)?.configured?'已配置 · 留空保持':'输入新的密钥'):''" @input="setDraft(field.path,inputValue($event,field))"/>
            <small>{{ fieldDescription(field) }}</small></div>
        </div></section>
        <section class="settings-section route-section"><div class="settings-section-head"><div><h3>模块模型路由</h3><p>主聊天换模型，不会强迫表情审核或认知模块一起切换。</p></div></div><datalist id="model-options"><option v-for="model in availableModels" :key="model" :value="model"/></datalist><div class="route-table"><div class="route-row route-header"><span>模块</span><span>当前模型</span><span>今日用量</span></div><div v-for="route in routes" :key="route.id" class="route-row"><span><strong>{{ route.label }}</strong><small>{{ route.inherited?'继承默认模型':'独立路由' }}</small></span><label><input :value="draft[`llm.module_models.${route.id}`]??(route.inherited?'':route.model)" list="model-options" :placeholder="`继承 ${getPath(state,'llm.model')}`" @input="setDraft(`llm.module_models.${route.id}`,($event.target as HTMLInputElement).value)"/></label><span class="route-usage"><strong>{{ formatNumber(route.usage?.total_tokens) }}</strong><small>{{ route.usage?.calls||0 }} 次</small></span></div></div></section>
        <section class="settings-section usage-section"><div class="settings-section-head"><div><h3>Token 与调用统计</h3><p>不保存 Prompt 或回复正文；缺失 usage 时会明确标记估算。</p></div><div class="segmented"><button v-for="item in ['today','7d','30d']" :key="item" :class="{active:range===item}" @click="loadUsage(item)">{{ item==='today'?'今天':item }}</button></div></div><div class="usage-cards"><article><small>总 Token</small><strong>{{ formatNumber(usage?.total_tokens) }}</strong><span>输入 {{ formatNumber(usage?.input_tokens) }} · 输出 {{ formatNumber(usage?.output_tokens) }}</span></article><article><small>调用 / 失败</small><strong>{{ formatNumber(usage?.calls) }} / {{ usage?.failures||0 }}</strong><span>{{ usage?.estimated_calls||0 }} 次为估算</span></article><article><small>平均 / P95 延迟</small><strong>{{ Number(usage?.avg_latency_ms||0).toFixed(0) }} / {{ Number(usage?.p95_latency_ms||0).toFixed(0) }}ms</strong><span>端到端模型请求</span></article></div><div class="module-usage"><article v-for="item in usage?.modules?.slice(0,10)" :key="item.module"><span><strong>{{ item.module }}</strong><small>{{ item.calls }} 次 · {{ formatNumber(item.total_tokens) }}</small></span><i><b :style="{width:`${Math.max(3,item.total_tokens/maxModuleTokens*100)}%`}"/></i></article></div></section>
      </template>
      <template v-else-if="['behavior','perception','expression','cognition'].includes(category)">
        <section v-if="category==='behavior'" class="autonomy-console"><div><small>AUTONOMY SAFETY SWITCH</small><h3>{{ autonomy?.running?'自主心跳正在运行':'自主心跳已暂停' }}</h3><p>今日已主动发言 {{ autonomy?.spoke_today||0 }} 次 · 已感知 {{ autonomy?.groups_known||0 }} 个群。暂停只关闭主动行为，私聊与 @ 回复仍保留。</p></div><button class="action-button" :class="{danger:autonomy?.running}" :disabled="controllingAutonomy" @click="controlAutonomy(autonomy?.running?'pause':'resume')"><Zap :size="15"/>{{ controllingAutonomy?'处理中':autonomy?.running?'暂停主动行为':'恢复主动行为' }}</button></section>
        <section v-if="category==='behavior'" class="preset-section"><span>快速预设</span><div><button v-for="preset in manifest.presets" :key="preset.id" @click="applyPreset(preset)">{{ preset.label }}</button></div><small>预设只生成差异，不会直接覆盖。</small></section>
        <section v-if="category==='behavior'" class="group-policy-editor"><div class="settings-section-head"><div><h3>逐群策略</h3><p>仅覆盖选中群；没有配置的群继承全局行为。所有改动都走右侧的验证、应用与回滚流程。</p></div><span>{{ Object.keys(groupPolicies).length }} 个群</span></div><div class="group-policy-list"><article v-for="(policy,id) in groupPolicies" :key="id"><div><strong>群 {{ id }}</strong><small>{{ policy.reply_enabled===false?'静默回复':policy.reply_only_when_mentioned===false?'可不 @ 回复':'仅 @ 回复' }} · {{ policy.autonomy===false?'禁止主动':'允许主动' }} · {{ policy.tools_enabled===false?'工具关闭':'工具可用' }}</small></div><span><button class="icon-button" aria-label="编辑群策略" @click="editGroupPolicy(String(id))"><Settings2 :size="16"/></button><button class="icon-button danger-icon" aria-label="删除群策略" @click="removeGroupPolicy(String(id))"><X :size="16"/></button></span></article></div><div class="group-policy-form"><input v-model="groupPolicyId" inputmode="numeric" placeholder="QQ 群号"/><label class="mini-switch"><input v-model="groupPolicy.reply_enabled" type="checkbox"/><span/>回复</label><label class="mini-switch"><input v-model="groupPolicy.reply_only_when_mentioned" type="checkbox"/><span/>需 @</label><label class="mini-switch"><input v-model="groupPolicy.autonomy" type="checkbox"/><span/>主动</label><label class="mini-switch"><input v-model="groupPolicy.tools_enabled" type="checkbox"/><span/>工具</label><label class="mini-switch"><input v-model="groupPolicy.stickers_enabled" type="checkbox"/><span/>表情</label><button class="action-button subtle" :disabled="!groupPolicyId" @click="saveGroupPolicy"><Save :size="15"/>保存预览</button></div></section>
        <section class="settings-section"><div class="settings-section-head"><div><h3>{{ currentCategory.label }}</h3><p>字段按风险与生效方式分层。</p></div></div><div class="field-grid"><div v-for="field in visibleFields" :key="field.path" class="field config-field"><div class="field-top"><label :for="field.path">{{ field.label }}</label><span :class="`risk-${field.risk}`">{{ field.risk==='green'?'安全':field.risk==='yellow'?'需重启':'高风险' }}</span></div><label v-if="field.type==='boolean'" class="switch"><input :id="field.path" type="checkbox" :checked="Boolean(displayValue(field))" @change="setDraft(field.path,($event.target as HTMLInputElement).checked)"/><span/></label><select v-else-if="field.type==='select'" :id="field.path" :value="displayValue(field)" @change="setDraft(field.path,($event.target as HTMLSelectElement).value)"><option v-for="option in field.options" :key="option">{{ option }}</option></select><input v-else :id="field.path" :type="field.type==='number'?'number':'text'" :min="field.min" :max="field.max" :value="displayValue(field)" @input="setDraft(field.path,inputValue($event,field))"/><small>{{ fieldDescription(field) }}</small></div></div></section>
      </template>
      <template v-else-if="category==='modules'"><section class="napcat-probe"><div><small>LIVE CHANNEL CHECK</small><h3>QQ / NapCat 实时诊断</h3><p>只调用 <code>get_login_info</code> 验证 action/echo 回路，不读聊天、不发消息。</p></div><button class="action-button" :disabled="probingNapcat" @click="probeNapcat"><TestTube2 :size="15"/>{{ probingNapcat?'诊断中':'立即自检' }}</button></section><div v-if="napcatProbe" class="napcat-result" :class="{failed:!napcatProbe.ok}"><span><Check v-if="napcatProbe.ok" :size="18"/><CircleAlert v-else :size="18"/></span><div><strong>{{ napcatProbe.ok?'NapCat 回路可用':'自检未通过' }}</strong><small>{{ napcatProbe.message }}</small></div><em v-if="napcatProbe.ok">{{ napcatProbe.latency_ms }} ms</em></div><div v-if="napcatProbe" class="napcat-metrics"><article><small>入站事件</small><strong>{{ formatNumber(napcatProbe.channel?.events_received) }}</strong><span>背压丢弃 {{ formatNumber(napcatProbe.channel?.events_backpressure_dropped) }}</span></article><article><small>出站成功</small><strong>{{ formatNumber(napcatProbe.channel?.outbound_successes) }}</strong><span>失败 {{ formatNumber(napcatProbe.channel?.outbound_failures) }}</span></article><article><small>待回执 action</small><strong>{{ formatNumber(napcatProbe.channel?.pending_actions) }}</strong><span>活跃任务 {{ formatNumber(napcatProbe.channel?.active_event_tasks) }}</span></article></div><p v-if="napcatProbe?.channel?.events_dropped" class="napcat-filter-note">已过滤 {{ formatNumber(napcatProbe.channel.events_dropped) }} 个协议帧（心跳、机器人回声或重复消息）；这不是消息积压。</p><div class="module-diagnostics"><article v-for="item in modules" :key="item.id"><span class="diag-icon"><Bot v-if="item.id==='gateway'" :size="17"/><Cpu v-else :size="17"/></span><div><strong>{{ item.label }}</strong><small>{{ item.message }}</small></div><StatusDot :status="item.status" :label="item.status"/></article></div></template>
      <template v-else-if="category==='permissions'"><section class="permission-section"><div class="permission-banner"><LockKeyhole :size="22"/><div><strong>Owner 是最终审批者</strong><p>管理员只能执行已授权操作，不能读取密钥或批准自我改写。</p></div></div><h3>Owner</h3><div class="identity-list"><article v-for="qq in permissions.owners" :key="qq"><span>O</span><div><strong>QQ {{ qq }}</strong><small>最高权限 · 不可由此页面移除</small></div><em>OWNER</em></article></div><div class="settings-section-head admin-head"><div><h3>管理员</h3><p>添加后立即写入权限存储并产生审计记录。</p></div><div class="admin-add"><input v-model="adminQQ" inputmode="numeric" placeholder="输入 QQ 号"/><button class="action-button" :disabled="!adminQQ" @click="addAdmin"><UserPlus :size="15"/>添加</button></div></div><div v-if="permissions.admins?.length" class="identity-list"><article v-for="qq in permissions.admins" :key="qq"><span>A</span><div><strong>QQ {{ qq }}</strong><small>管理员 · 受 Owner 策略约束</small></div><button class="icon-button" aria-label="移除管理员" @click="removeAdmin(qq)"><X :size="17"/></button></article></div><EmptyState v-else title="没有额外管理员" detail="目前只有 Owner 可以操作控制台。"/><h3>工具权限矩阵</h3><p class="tools-note">等级含义：0=封禁 · 1=只读 · 2=普通用户 · 3=管理员 · 4=Owner。修改后立即生效，无需重启。</p><div v-if="toolList.length" class="tool-perm-table"><div class="tool-perm-header"><span>工具</span><span>说明</span><span>最低等级</span><span>状态</span></div><article v-for="tool in toolList" :key="tool.name" class="tool-perm-row"><span class="tool-name"><strong>{{ tool.name }}</strong></span><span class="tool-desc"><small>{{ tool.description }}</small></span><span class="tool-level"><select :value="tool.min_level" @change="updateToolLevel(tool.name, Number(($event.target as HTMLSelectElement).value))"><option v-for="opt in toolLevelOptions" :key="opt.value" :value="opt.value">{{ opt.label }}</option></select></span><span class="tool-status"><span :class="['tool-badge', tool.enabled?'enabled':'disabled']">{{ tool.enabled?'可用':'停用' }}</span><span v-if="tool.danger" class="tool-badge danger">高危</span></span></article></div><EmptyState v-else title="工具列表为空" detail="核心工具尚未注册。"/></section></template>
    </main>
    <aside class="change-panel panel"><header><span :class="`change-signal ${riskTone}`"><i/></span><div><small>CHANGE PREVIEW</small><strong>本次修改</strong></div><span>{{ changes.length }} 项</span></header><div v-if="changes.length" class="change-list"><article v-for="item in changes" :key="item.path"><div><strong>{{ item.field?.label||item.path.split('.').slice(-2).join(' / ') }}</strong><small>{{ item.impact.join('、') }}</small></div><span :class="`risk-${item.risk}`">{{ item.restart?'重启':'热应用' }}</span></article></div><EmptyState v-else title="还没有修改" detail="更改字段或选择预设后，这里会先展示影响与风险。"/><footer><div v-if="changes.length" class="change-warning"><CircleAlert :size="15"/><span>{{ riskTone==='red'?'包含高风险能力，需要再次确认。':changes.some(c=>c.restart)?'应用后会受控重启并执行健康检查。':'这些字段可以直接生效。' }}</span></div><button class="action-button" :disabled="!changes.length||validating" @click="prepareChange"><Save :size="16"/>{{ validating?'正在校验…':'验证并生成变更' }}</button><button v-if="changes.length" class="reset-button" @click="draft={}"><RotateCcw :size="14"/>清空修改</button></footer><section class="history-section"><div class="history-head"><div><small>CHANGE HISTORY</small><strong>配置历史与回滚</strong></div><span>{{ history.length }} 条</span></div><p class="history-note">只显示脱敏快照；待应用变更可驳回，已应用的绿色变更可以立即回滚，黄色变更会受控重启。</p><div v-if="history.length" class="history-list"><article v-for="item in history" :key="item.id" class="history-item"><div class="history-item-main"><strong>{{ changeLabel(item) }}</strong><small>{{ formatDate(item.created_at) }} · {{ item.id }}</small><span :class="`history-status ${item.status}`">{{ item.status==='applied'?'已应用':item.status==='rolled_back'?'已回滚':item.status==='rejected'?'已驳回':'待应用' }}<small v-if="item.status==='rejected'&&item.rejection_reason" class="history-reason">{{ item.rejection_reason }}</small></span></div><span class="history-actions"><button v-if="canReject(item)" class="history-reject" :disabled="rejecting===item.id" @click="rejectChange(item)"><X :size="13"/>{{ rejecting===item.id?'驳回中':'驳回' }}</button><button v-if="canRollback(item)" class="history-rollback" :disabled="rollingBack===item.id" @click="rollbackChange(item)"><RotateCcw :size="13"/>{{ rollingBack===item.id?'回滚中':'一键回滚' }}</button></span></article></div><EmptyState v-else title="还没有配置历史" detail="应用一次配置变更后，审计记录会出现在这里。"/></section></aside>
  </div>
  <div v-if="pendingChange" class="modal-backdrop" @click.self="pendingChange=null"><section class="modal confirm-change"><header class="modal-head"><Shield :size="19"/><strong>确认应用配置变更</strong><button class="icon-button" @click="pendingChange=null"><X :size="18"/></button></header><div class="modal-body"><div class="confirm-id">审计编号 <b>{{ pendingChange.id }}</b><span :class="`risk-${pendingChange.risk}`">{{ pendingChange.risk }}</span></div><h3>将影响</h3><div class="impact-tags"><span v-for="item in pendingChange.impact" :key="item">{{ item }}</span></div><p>应用 LLM 变更前会先探测模型网关与模型列表；预检失败会保留待应用状态，不会替换当前可用连接。{{ pendingChange.restart_required?'通过后 Anima 将由 systemd 受控重启，并执行健康检查。':'通过后这些配置将在当前进程中应用，并写入审计记录。' }}</p></div><footer class="modal-foot"><button class="action-button subtle" @click="pendingChange=null">暂不应用</button><button class="action-button" :disabled="applying" @click="applyChange"><Check :size="16"/>{{ applying?'应用中…':'确认应用' }}</button></footer></section></div>
</section></template>

